/**
 * models/BlogPost.js
 * ---------------------------------------------------------------------------
 * Required schema (spec Phase 1):
 *   title   (String, required)
 *   content (String, required)
 *   author  (ObjectId, ref 'User', required)
 *   timestamps (auto-generated by { timestamps: true })
 *
 * Relationship: BlogPost.author --(ref)--> User._id
 *               Comment.post    --(ref)--> BlogPost._id  (defined in Comment.js)
 *
 * The `comments` VIRTUAL is what lets GET /api/blog/:id populate the post's
 * comments in one query (Phase 4: "populated with ... all associated comments").
 * A virtual is not stored in MongoDB; it is a computed join definition.
 * ---------------------------------------------------------------------------
 */
const mongoose = require('mongoose');

const blogPostSchema = new mongoose.Schema(
  {
    title: {
      type: String,
      required: [true, 'Post title is required'],
      trim: true,
      maxlength: [150, 'Title must be at most 150 characters'],
    },
    content: {
      type: String,
      required: [true, 'Post content is required'],
      trim: true,
    },
    author: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: [true, 'A post must have an author'],
      index: true,
    },
    // Suggested optional extras (not required by the spec; used by the UI cards)
    excerpt: {
      type: String,
      trim: true,
      maxlength: [300, 'Excerpt must be at most 300 characters'],
      default: '',
    },
    tags: {
      type: [String],
      default: [],
    },
  },
  {
    timestamps: true, // -> createdAt / updatedAt (spec: "timestamps (auto-generated)")
    toJSON: { virtuals: true }, // so `comments` appears in res.json()
    toObject: { virtuals: true },
  }
);

/**
 * Virtual populate: BlogPost.comments => Comment.find({ post: <this._id> })
 * Used by GET /api/blog/:id with:
 *   .populate({ path: 'comments', populate: { path: 'author', select: 'username' } })
 */
blogPostSchema.virtual('comments', {
  ref: 'Comment',
  localField: '_id',
  foreignField: 'post',
  justOne: false,
});

// Newest first for GET /api/blog
blogPostSchema.index({ createdAt: -1 });

module.exports = mongoose.model('BlogPost', blogPostSchema);
